-- Factory Stock: the whole schema, as it stood in SQLite after every start-up migration
-- (src/db.js addColumn steps folded into each CREATE TABLE).
-- Conversions from SQLite:
--   INTEGER PRIMARY KEY  -> integer generated by default as identity (integer, so ids are JS numbers;
--                           "by default" so the copy script can keep the real ids)
--   REAL                 -> double precision;  0/1 flags stay integer (code compares them to 1)
--   datetime('now','localtime') -> Melbourne wall-clock text 'YYYY-MM-DD HH:MM:SS', whatever the
--                           server's own time zone is (the cloud runs in UTC)

-- first_number('Bay 6') = 6: the bay number, read the same way as "Move the line along" reads it
-- (first run of digits in the name; 9999 when there is none). Used to sort vans by how far along they are.
-- Not STRICT: a null name gives 9999 too. LEAST keeps an absurdly long digit run from overflowing.
CREATE FUNCTION first_number(s text) RETURNS integer
LANGUAGE sql IMMUTABLE PARALLEL SAFE
AS $$ SELECT LEAST(COALESCE(substring(s FROM '[0-9]+')::numeric, 9999), 2147483647)::integer $$;

CREATE TABLE items (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  sku text UNIQUE NOT NULL,
  name text NOT NULL,
  category text NOT NULL DEFAULT 'General',
  supplier text NOT NULL DEFAULT '',
  unit text NOT NULL DEFAULT 'ea',
  -- 'stock' = kept on the shelf; 'per-van' = ordered for each van (chassis, furniture, cladding…)
  kind text NOT NULL DEFAULT 'stock',
  on_hand double precision NOT NULL DEFAULT 0,
  reorder_level double precision NOT NULL DEFAULT 0,
  location text NOT NULL DEFAULT '',
  notes text NOT NULL DEFAULT '',
  active integer NOT NULL DEFAULT 1,
  -- Which production-plan column (e.g. "Battery", "FRIDGE") the item shows under.
  plan_column text NOT NULL DEFAULT '',
  -- Photo file name ("<id>-<time>.jpg"; the thumbnail is "<id>-<time>-t.jpg").
  photo text NOT NULL DEFAULT '',
  -- Where the item is stored (floor_areas.id).
  area_id integer,
  -- Which trade (electrician, builder, cladding, plumber, finisher) the part is for.
  trade text NOT NULL DEFAULT '',
  -- Set only by a real count (movement type 'count'); '' = not counted yet.
  last_counted text NOT NULL DEFAULT '',
  -- 1 = an "as per plan" catch-all (PLAN-…) item, not a real part on a shelf.
  placeholder integer NOT NULL DEFAULT 0,
  -- What one unit is ("1 length = 6.5 m", "set = 1 van"), shown next to every quantity on the floor.
  unit_size text NOT NULL DEFAULT '',
  -- Shelf top-up target: when stock falls below the reorder level, order back up to this (0 = the level).
  order_up_to double precision NOT NULL DEFAULT 0
);

-- "When the order says X, the van needs item Y". Conditions are one per line:
--   LABEL ~ regex     field value matches (case-insensitive)
--   LABEL !~ regex    field value does not match (missing field counts as not matching)
--   LABEL ?           field is filled in and not "no"/"none"/"0"
--   *                 always (standard part on every van)
CREATE TABLE rules (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name text NOT NULL DEFAULT '',
  conditions text NOT NULL,
  item_id integer NOT NULL REFERENCES items(id) ON DELETE CASCADE,
  qty text NOT NULL DEFAULT '1',
  spec_fields text NOT NULL DEFAULT '',
  active integer NOT NULL DEFAULT 1,
  sort integer NOT NULL DEFAULT 0
);

CREATE TABLE vans (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  chassis text UNIQUE NOT NULL,
  customer text NOT NULL DEFAULT '',
  dealer text NOT NULL DEFAULT '',
  model text NOT NULL DEFAULT '',
  length text NOT NULL DEFAULT '',
  floor_plan text NOT NULL DEFAULT '',
  colour text NOT NULL DEFAULT '',
  atm text NOT NULL DEFAULT '',
  quote_no text NOT NULL DEFAULT '',
  order_date text NOT NULL DEFAULT '',
  eta text NOT NULL DEFAULT '',
  -- planned -> in_production -> completed
  status text NOT NULL DEFAULT 'planned',
  reviewed integer NOT NULL DEFAULT 0,
  notes text NOT NULL DEFAULT '',
  created_at text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'Australia/Melbourne','YYYY-MM-DD HH24:MI:SS'),
  -- Where the van is parked on the floor (floor_areas.id).
  area_id integer,
  -- Office-set build sequence (1, 2, 3…) for planned vans; null = use the due date.
  build_order integer
);

CREATE TABLE order_fields (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  van_id integer NOT NULL REFERENCES vans(id) ON DELETE CASCADE,
  section text NOT NULL DEFAULT '',
  label text NOT NULL,
  value text NOT NULL DEFAULT '',
  note text NOT NULL DEFAULT '',
  sort integer NOT NULL DEFAULT 0
);

-- Parts list for each van. reserved = set aside from stock, issued = handed to the floor.
CREATE TABLE van_lines (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  van_id integer NOT NULL REFERENCES vans(id) ON DELETE CASCADE,
  item_id integer NOT NULL REFERENCES items(id),
  qty double precision NOT NULL,
  reserved double precision NOT NULL DEFAULT 0,
  issued double precision NOT NULL DEFAULT 0,
  spec text NOT NULL DEFAULT '',
  source text NOT NULL DEFAULT 'rule',  -- 'rule' or 'manual'
  rule_id integer,
  note text NOT NULL DEFAULT '',
  plan_column text NOT NULL DEFAULT '',
  -- Free-text order reference as written on the plan ("Order 98", "Arizon 24").
  po_ref text NOT NULL DEFAULT '',
  -- The part of `reserved` that was received for this particular van (a PO for the van, a grey plan
  -- cell, "Assign to van"). Re-prioritising never moves it; only reserved - reserved_firm can move.
  reserved_firm double precision NOT NULL DEFAULT 0,
  -- 1: this van's part was borrowed by another van on the floor, so it must be re-ordered now.
  urgent integer NOT NULL DEFAULT 0,
  -- '' (normal), 'customer' (customer supplies it), 'tbd' (to be decided), 'not_ordered'.
  state text NOT NULL DEFAULT '',
  -- Production-plan columns whose plan line was merged into this line (JSON list).
  merged_cols text NOT NULL DEFAULT ''
);

CREATE TABLE purchase_orders (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  po_no text NOT NULL,
  supplier text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'open',  -- open / closed
  notes text NOT NULL DEFAULT '',
  created_at text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'Australia/Melbourne','YYYY-MM-DD HH24:MI:SS'),
  ordered_at text NOT NULL DEFAULT '',
  expected text NOT NULL DEFAULT '',
  needs_check integer NOT NULL DEFAULT 0
);

CREATE TABLE po_lines (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  po_id integer NOT NULL REFERENCES purchase_orders(id) ON DELETE CASCADE,
  item_id integer NOT NULL REFERENCES items(id),
  qty double precision NOT NULL,
  received double precision NOT NULL DEFAULT 0,
  van_id integer REFERENCES vans(id) ON DELETE SET NULL,
  -- What exactly was ordered (colour, size, model) — copied from the van line's spec.
  spec text NOT NULL DEFAULT '',
  -- Backorder date, and the balance the supplier cancelled.
  expected text NOT NULL DEFAULT '',
  closed double precision NOT NULL DEFAULT 0
);

-- Identity numbers are never reused, so a phone's Undo can't hit another movement
-- (what AUTOINCREMENT did in SQLite).
CREATE TABLE movements (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  item_id integer NOT NULL REFERENCES items(id) ON DELETE CASCADE,
  qty double precision NOT NULL,
  type text NOT NULL,          -- receive / issue / adjust / return / count
  van_id integer REFERENCES vans(id) ON DELETE SET NULL,
  ref text NOT NULL DEFAULT '',
  note text NOT NULL DEFAULT '',
  at text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'Australia/Melbourne','YYYY-MM-DD HH24:MI:SS'),
  -- Who did it (worker name from the floor screen).
  worker text NOT NULL DEFAULT '',
  -- For a part taken on the floor: what the take changed (JSON), so Undo can put it all back.
  undo text NOT NULL DEFAULT '',
  -- 1 once the office ticked it on the weekly "Stock checks" page.
  ack integer NOT NULL DEFAULT 0,
  -- Which login made it ("undo only your own"); null on movements from before logins.
  user_id integer
);

CREATE TABLE settings (key text PRIMARY KEY, value text NOT NULL);

-- ── Factory floor: areas (bays, yard spots, gates, racks, workstations, walls) in metres ──
CREATE TABLE floor_areas (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kind text NOT NULL,          -- bay / yard / gate_in / gate_out / storage / work / wall / building
  name text NOT NULL DEFAULT '',
  x double precision NOT NULL, y double precision NOT NULL, w double precision NOT NULL, h double precision NOT NULL,
  sort integer NOT NULL DEFAULT 0,
  notes text NOT NULL DEFAULT ''
);

CREATE TABLE van_notes (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  van_id integer NOT NULL REFERENCES vans(id) ON DELETE CASCADE,
  text text NOT NULL,
  worker text NOT NULL DEFAULT '',
  created_at text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'Australia/Melbourne','YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE reminders (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  van_id integer REFERENCES vans(id) ON DELETE CASCADE,
  text text NOT NULL,
  due text NOT NULL DEFAULT '',
  done integer NOT NULL DEFAULT 0,
  worker text NOT NULL DEFAULT '',
  created_at text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'Australia/Melbourne','YYYY-MM-DD HH24:MI:SS'),
  done_at text NOT NULL DEFAULT '',
  -- Reminders created automatically (e.g. "drawing:<order line>") so they're never added twice.
  source text NOT NULL DEFAULT '',
  -- Which trade it is for; '' means everyone.
  trade text NOT NULL DEFAULT ''
);

-- Every change to what is set aside for a van (and every clean-up change), with before -> after.
CREATE TABLE allocation_log (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  at text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'Australia/Melbourne','YYYY-MM-DD HH24:MI:SS'),
  reason text NOT NULL,              -- 'tidy:lock', 'reprioritise', 'borrow', 'fitted', 'count'…
  van_id integer,
  item_id integer,
  line_id integer,
  field text NOT NULL DEFAULT '',    -- what changed: 'reserved', 'qty', 'on_hand', 'item', 'flag'…
  before text NOT NULL DEFAULT '',
  after text NOT NULL DEFAULT '',
  worker text NOT NULL DEFAULT '',
  note text NOT NULL DEFAULT '',
  -- The numeric change of `reserved` / `reserved_firm` on a line (so a figure can be explained).
  change double precision,
  firm_change double precision,
  -- 1 once the office ticked it on the weekly "Stock checks" page.
  ack integer NOT NULL DEFAULT 0
);

-- A rack / trade count: what the system expected for each item when the count was opened.
CREATE TABLE count_sessions (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  scope text NOT NULL,               -- 'area:<id>', 'norack', 'trade:<trade>'
  label text NOT NULL DEFAULT '',
  opened_at text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'Australia/Melbourne','YYYY-MM-DD HH24:MI:SS'),
  opened_by text NOT NULL DEFAULT '',
  last_move_id integer NOT NULL DEFAULT 0,
  expected text NOT NULL DEFAULT '{}',   -- {itemId: on_hand when opened}
  closed_at text NOT NULL DEFAULT ''
);

-- Lead time per supplier (days from ordering to arriving). lead_confirmed = 0: the 14-day default is assumed.
CREATE TABLE suppliers (
  name text PRIMARY KEY,
  lead_days integer NOT NULL DEFAULT 14,
  lead_confirmed integer NOT NULL DEFAULT 0
);

-- ── Logins and job roles (see src/auth.js) ──
-- users: one login per person. username is unique whatever its capitals (the lower() index below;
-- look it up with lower(username) = lower(?)). trade is set for workers only. pass_hash =
-- scrypt$N$r$p$salt$hash (never the password). active = 0: the login is turned off.
-- must_change = 1: choose a new password at the next log in.
CREATE TABLE users (
  id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username text NOT NULL,
  name text NOT NULL,
  role text NOT NULL CHECK (role IN ('owner','office','stores','leadhand','worker')),
  trade text NOT NULL DEFAULT '',
  pass_hash text NOT NULL,
  active integer NOT NULL DEFAULT 1,
  must_change integer NOT NULL DEFAULT 0,
  created_at text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'Australia/Melbourne','YYYY-MM-DD HH24:MI:SS'),
  created_by text NOT NULL DEFAULT '',
  last_login text NOT NULL DEFAULT ''
);
CREATE UNIQUE INDEX ux_users_username ON users (lower(username));

-- sessions: one row per logged-in browser / phone. Only sha256 of the cookie's random token is kept;
-- times are milliseconds (Date.now()), hence bigint. Expiry slides: 30 days from the last use.
CREATE TABLE sessions (
  token_hash text PRIMARY KEY,
  user_id integer NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at bigint NOT NULL,
  last_seen bigint NOT NULL,
  expires_at bigint NOT NULL,
  ip text NOT NULL DEFAULT '',
  ua text NOT NULL DEFAULT ''
);

-- Login lock-outs (src/auth.js createThrottle), kept here instead of in memory because cloud
-- instances come and go. Times are milliseconds (Date.now()).
CREATE TABLE login_throttle (key text primary key, fails integer, first_at bigint, locked_until bigint);

-- The answer already given to a floor request id (rid), so a phone that sends the same delivery twice
-- books it once (was the in-memory floorReceipts). at = milliseconds (Date.now()).
CREATE TABLE request_receipts (rid text primary key, out jsonb, at bigint);

CREATE INDEX ix_lines_van ON van_lines(van_id);
CREATE INDEX ix_lines_item ON van_lines(item_id);
CREATE INDEX ix_lines_van_item ON van_lines(van_id, item_id);
CREATE INDEX ix_fields_van ON order_fields(van_id);
CREATE INDEX ix_po_lines_item ON po_lines(item_id);
CREATE INDEX ix_po_lines_van_item ON po_lines(van_id, item_id);
CREATE INDEX ix_moves_item ON movements(item_id);
CREATE INDEX ix_moves_van ON movements(van_id);
CREATE INDEX ix_moves_item_at ON movements(item_id, at);
CREATE INDEX ix_moves_type_at ON movements(type, at);
CREATE INDEX ix_notes_van ON van_notes(van_id);
CREATE INDEX ix_rem_van ON reminders(van_id);
CREATE INDEX ix_alog_reason ON allocation_log(reason);
CREATE INDEX ix_alog_line ON allocation_log(line_id);
CREATE INDEX ix_alog_item ON allocation_log(item_id);
CREATE INDEX ix_alog_at ON allocation_log(at);
CREATE INDEX ix_sessions_user ON sessions(user_id);

-- The firm part can never be more than what is set aside (or below 0), whatever code changes it.
CREATE FUNCTION firm_cap() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.reserved_firm := GREATEST(0, LEAST(NEW.reserved_firm, NEW.reserved));
  RETURN NEW;
END
$$;
CREATE TRIGGER trg_firm_cap BEFORE UPDATE OF reserved, reserved_firm ON van_lines
  FOR EACH ROW EXECUTE FUNCTION firm_cap();

-- Bumped by every write transaction (db.js writeTx), so screens can tell their data is out of date.
INSERT INTO settings(key, value) VALUES ('data_version', '0');
